/* Default Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Default Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 300 50% 100%;
    --foreground: 300 0% 3.94%;
    --card: 300 50% 100%;
    --card-foreground: 300 0% 3.94%;
    --popover: 300 50% 100%;
    --popover-foreground: 300 0% 3.94%;
    --primary: 330 0% 9.05%;
    --primary-foreground: 0 0% 98.03%;
    --secondary: 300 0% 96.06%;
    --secondary-foreground: 330 0% 9.05%;
    --muted: 300 0% 96.06%;
    --muted-foreground: 300 0% 45.15%;
    --accent: 300 0% 96.06%;
    --accent-foreground: 330 0% 9.05%;
    --destructive: 354.09 99.92% 44.64%;
    --destructive-foreground: 300 50% 100%;
    --border: 330 0% 89.82%;
    --input: 330 0% 89.82%;
    --ring: 300 0% 63.02%;
    --chart-1: 211.8 99.99% 78.65%;
    --chart-2: 217.41 91.37% 59.58%;
    --chart-3: 221.43 86.37% 54.06%;
    --chart-4: 223.66 78.72% 47.86%;
    --chart-5: 226.54 70.01% 39.92%;
    --sidebar: 0 0% 98.03%;
    --sidebar-foreground: 300 0% 3.94%;
    --sidebar-primary: 330 0% 9.05%;
    --sidebar-primary-foreground: 0 0% 98.03%;
    --sidebar-accent: 300 0% 96.06%;
    --sidebar-accent-foreground: 330 0% 9.05%;
    --sidebar-border: 330 0% 89.82%;
    --sidebar-ring: 300 0% 63.02%;
    --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    --radius: 0.625rem;
    --shadow-x: 0;
    --shadow-y: 1px;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-opacity: 0.1;
    --shadow-color: 0 0% 0%;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
    --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);
    --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);
    --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
    --spacing: 0.25rem;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 300 0% 3.94%;
    --foreground: 0 0% 98.03%;
    --card: 330 0% 9.05%;
    --card-foreground: 0 0% 98.03%;
    --popover: 300 0% 14.94%;
    --popover-foreground: 0 0% 98.03%;
    --primary: 330 0% 89.82%;
    --primary-foreground: 330 0% 9.05%;
    --secondary: 300 0% 14.94%;
    --secondary-foreground: 0 0% 98.03%;
    --muted: 300 0% 14.94%;
    --muted-foreground: 300 0% 63.02%;
    --accent: 300 0% 25.05%;
    --accent-foreground: 0 0% 98.03%;
    --destructive: 358.93 99.97% 69.87%;
    --destructive-foreground: 0 0% 98.03%;
    --border: 0 0% 15.51%;
    --input: 330 0% 20.39%;
    --ring: 300 0% 45.15%;
    --chart-1: 211.8 99.99% 78.65%;
    --chart-2: 217.41 91.37% 59.58%;
    --chart-3: 221.43 86.37% 54.06%;
    --chart-4: 223.66 78.72% 47.86%;
    --chart-5: 226.54 70.01% 39.92%;
    --sidebar: 330 0% 9.05%;
    --sidebar-foreground: 0 0% 98.03%;
    --sidebar-primary: 225.35 84.1% 48.98%;
    --sidebar-primary-foreground: 0 0% 98.03%;
    --sidebar-accent: 300 0% 14.94%;
    --sidebar-accent-foreground: 0 0% 98.03%;
    --sidebar-border: 0 0% 15.51%;
    --sidebar-ring: 0 0% 32.2%;
    --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    --radius: 0.625rem;
    --shadow-x: 0;
    --shadow-y: 1px;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-opacity: 0.1;
    --shadow-color: 0 0% 0%;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 1px 2px -1px hsl(0 0% 0% / 0.10);
    --shadow-md: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 2px 4px -1px hsl(0 0% 0% / 0.10);
    --shadow-lg: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 4px 6px -1px hsl(0 0% 0% / 0.10);
    --shadow-xl: 0 1px 3px 0px hsl(0 0% 0% / 0.10), 0 8px 10px -1px hsl(0 0% 0% / 0.10);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
    --spacing: 0.25rem;
  }

}
